import { existsSync } from 'node:fs';
import { mkdir, readFile, readdir, writeFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { performance } from 'node:perf_hooks';
import { aggregateReliability } from './lib/reliability-aggregation.mjs';

const ROOT = process.cwd();
const OUT_DIR = resolve(ROOT, 'artifacts/agent-dev-benefit-eval');

async function read(path) {
  return await readFile(resolve(ROOT, path), 'utf8');
}

async function walk(dir, predicate = () => true) {
  const results = [];
  async function visit(abs) {
    for (const entry of await readdir(abs, { withFileTypes: true })) {
      if (entry.name === 'node_modules' || entry.name === '.git' || entry.name === 'dist') continue;
      const full = join(abs, entry.name);
      if (entry.isDirectory()) await visit(full);
      else if (predicate(full)) results.push(full);
    }
  }
  await visit(resolve(ROOT, dir));
  return results;
}

function countMatches(text, pattern) {
  return [...text.matchAll(pattern)].length;
}

function extractScenarioIds(registryText) {
  const match = registryText.match(/export const AGENT_DEV_SCENARIOS = \[([\s\S]*?)\] as const/);
  return match ? [...match[1].matchAll(/\{\s*id:\s*'([^']+)'/g)].map((entry) => entry[1]) : [];
}

function packageInstalled(name) {
  const normalized = name.startsWith('@')
    ? name.replace('/', '\\')
    : name;
  return existsSync(resolve(ROOT, 'node_modules', ...normalized.split(/[\\/]/)));
}

async function scanSelectorCoverage() {
  const files = await walk('src', (file) => /\.(tsx|ts)$/.test(file));
  let testIdCount = 0;
  let interactiveTagCount = 0;
  let interactiveWithoutInlineTestId = 0;
  for (const file of files) {
    const text = await readFile(file, 'utf8');
    testIdCount += countMatches(text, /data-testid=/g);
    const tags = [...text.matchAll(/<(?<tag>button|input|select|textarea|a)\b(?<attrs>[^>]*)>/g)];
    interactiveTagCount += tags.length;
    interactiveWithoutInlineTestId += tags.filter((match) => !String(match.groups?.attrs ?? '').includes('data-testid')).length;
  }
  return {
    fileCount: files.length,
    testIdCount,
    interactiveTagCount,
    interactiveWithoutInlineTestId,
    inlineSelectorCoverage: interactiveTagCount === 0
      ? 1
      : Number(((interactiveTagCount - interactiveWithoutInlineTestId) / interactiveTagCount).toFixed(3)),
  };
}

function renderMarkdown(report) {
  const tools = report.externalTools.map((tool) => (
    `| ${tool.package} | ${tool.installed ? 'yes' : 'no'} | ${tool.role} |`
  )).join('\n');
  const reliability = report.reliability;
  const incompleteRows = reliability.incomplete.cases.map((item) => (
    `| ${item.id} | ${item.statuses.join(', ')} | ${item.safety ? 'yes' : 'no'} |`
  )).join('\n') || '| none | none | n/a |';
  const reasons = reliability.reasons.length > 0
    ? reliability.reasons.map((reason) => `- ${reason}`).join('\n')
    : '- none';
  return `# Agent Dev Benefit Evaluation

Generated: ${report.generatedAt}

## Summary

| Metric | Value |
| --- | ---: |
| Dev scenarios | ${report.agentDev.scenarioCount} |
| hostApi.agentDev methods | ${report.agentDev.hostApiMethodCount} |
| E2E agent-dev helpers | ${report.agentDev.e2eHelperCount} |
| Runtime schema assertions | ${report.agentDev.schemaAssertionCount} |
| Basic a11y rule families | ${report.quality.a11yRuleCount} |
| Renderer files scanned | ${report.selectorCoverage.fileCount} |
| data-testid occurrences | ${report.selectorCoverage.testIdCount} |
| Interactive tags scanned | ${report.selectorCoverage.interactiveTagCount} |
| Inline selector coverage | ${Math.round(report.selectorCoverage.inlineSelectorCoverage * 100)}% |

## External Tool Readiness

| Package | Installed | Role |
| --- | --- | --- |
${tools}

## Deterministic Reliability Oracle

This section uses the checked-in deterministic fixture. It is not evidence of real-provider, human, or model generalization.

| Metric | Value |
| --- | ---: |
| Oracle | ${reliability.oracle} |
| Registered case denominator | ${reliability.rawDenominator.registeredCases} |
| Complete case denominator | ${reliability.rawDenominator.completeCases} |
| Incomplete cases (excluded) | ${reliability.incomplete.count} |
| pass^k (${reliability.k}) | ${reliability.passPowK.numerator}/${reliability.passPowK.denominator} (${(reliability.passPowK.rate * 100).toFixed(2)}%) |
| pass@k (${reliability.k}) | ${reliability.passAtK.numerator}/${reliability.passAtK.denominator} (${(reliability.passAtK.rate * 100).toFixed(2)}%) |
| Per-trial success | ${reliability.trialSuccess.successful}/${reliability.trialSuccess.total} (${(reliability.trialSuccess.rate * 100).toFixed(2)}%) |
| Flake | ${reliability.flake.cases}/${reliability.flake.denominator} (${(reliability.flake.rate * 100).toFixed(2)}%) |
| Positive anchors passed | ${reliability.anchors.positive.passed}/${reliability.anchors.positive.total} |
| Negative anchors passed | ${reliability.anchors.negative.passed}/${reliability.anchors.negative.total} |
| Gate | ${reliability.gate} |

pass^k means every one of the first k trials passed. pass@k means at least one of the first k trials passed. They are intentionally separate. A later fixed rerun exposes a flake but does not replace the first failed attempt.

### Incomplete Cases

| Case | Status | Safety |
| --- | --- | --- |
${incompleteRows}

### Gate Reasons

${reasons}

## Interpretation

- The current in-repo implementation already gives agents ${report.agentDev.scenarioCount} deterministic page entry points and ${report.agentDev.e2eHelperCount} E2E helpers without depending on new packages.
- Schema assertions now reject malformed agent-dev payloads at the Main host-api boundary.
- Basic a11y and visual artifact generation are available through Playwright today; axe/Argos can replace the fallback scanners once supply-chain policy allows installing them.
- The selector coverage metric is a heuristic. It is useful as a trend line, not as a precise accessibility or E2E quality proof.
- The reliability oracle evaluates only the checked-in deterministic fixture and makes no claim about real-provider or human generalization.
`;
}

const start = performance.now();
const [
  scenarioRegistry,
  hostApi,
  e2eFixture,
  schemaText,
  a11yText,
  reliabilityFixtureText,
] = await Promise.all([
  read('shared/agent-dev/scenarios.ts'),
  read('src/lib/host-api.ts'),
  read('tests/e2e/fixtures/electron.ts'),
  read('shared/host-api/agent-dev-schemas.ts'),
  read('tests/e2e/fixtures/a11y.ts'),
  read('shared/agent-dev/reliability-fixture.json'),
]);

const scenarioIds = extractScenarioIds(scenarioRegistry);
const hostApiAgentDevBlock = hostApi.match(/agentDev:\s*\{([\s\S]*?)\n  \},\n  providers:/)?.[1] ?? '';
const reliabilityFixture = JSON.parse(reliabilityFixtureText);
const report = {
  generatedAt: new Date().toISOString(),
  durationMs: 0,
  agentDev: {
    scenarioCount: scenarioIds.length,
    scenarios: scenarioIds,
    hostApiMethodCount: countMatches(hostApiAgentDevBlock, /^\s{4}[A-Za-z][A-Za-z0-9_]*:/gm),
    e2eHelperCount: countMatches(e2eFixture, /export async function (openAgentDevScenario|getAgentDevSnapshot|configureAgentDevHostReplay|getAgentDevHostCalls)/g),
    schemaAssertionCount: countMatches(schemaText, /export function assertAgentDev/g),
  },
  quality: {
    a11yRuleCount: countMatches(a11yText, /add\('([^']+)'/g),
    visualArtifactSpec: existsSync(resolve(ROOT, 'tests/e2e/agent-dev-quality.spec.ts')),
    workbenchScript: existsSync(resolve(ROOT, 'scripts/agent-dev-workbench.mjs')),
  },
  selectorCoverage: await scanSelectorCoverage(),
  reliability: aggregateReliability(reliabilityFixture.config, reliabilityFixture),
  externalTools: [
    { package: '@axe-core/playwright', installed: packageInstalled('@axe-core/playwright'), role: 'strict a11y scanning' },
    { package: '@ladle/react', installed: packageInstalled('@ladle/react'), role: 'component scenario workbench' },
    { package: '@argos-ci/playwright', installed: packageInstalled('@argos-ci/playwright'), role: 'hosted visual regression' },
    { package: '@vitest/browser', installed: packageInstalled('@vitest/browser'), role: 'browser component testing' },
    { package: '@testing-library/user-event', installed: packageInstalled('@testing-library/user-event'), role: 'realistic user interactions' },
    { package: 'knip', installed: packageInstalled('knip'), role: 'unused files/deps/exports' },
    { package: 'ajv', installed: packageInstalled('ajv'), role: 'JSON schema validation engine' },
  ],
};
report.durationMs = Number((performance.now() - start).toFixed(1));

await mkdir(OUT_DIR, { recursive: true });
await writeFile(resolve(OUT_DIR, 'report.json'), JSON.stringify(report, null, 2), 'utf8');
await writeFile(resolve(OUT_DIR, 'report.md'), renderMarkdown(report), 'utf8');
console.log(JSON.stringify(report, null, 2));
"},{"path":"harness/specs/tasks/harness-gap-reliability-aggregation.md","content":"# E01 — Agent Dev benefit reliability aggregation

## Goal

Extend the existing Agent Dev benefit report with a deterministic reliability oracle. Reuse `shared/agent-dev/scenarios.ts` and the existing report; do not introduce another metrics platform.

## Pre-registration

The fixture at `shared/agent-dev/reliability-fixture.json` pre-registers:

- `k = 3`;
- at least `20` complete cases;
- a flake-rate threshold of `0.1`.

The fixture is a deterministic in-repo oracle. It does not represent a real model, provider, human study, or generalization result.

## Implementation

1. Aggregate complete eligible cases into deterministic `pass^k` and `pass@k` values.
2. Emit per-case and per-trial first-attempt outcomes and aggregate per-trial success.
3. Detect a flake only when the first attempt fails and a fixed rerun later succeeds. Preserve the first failure.
4. Retain `missing`, `timeout`, `crash`, and `skip` cases as incomplete and exclude those cases from denominators.
5. Aggregate positive and negative anchors separately. A positive anchor must pass every trial; a negative anchor must reject every trial. Any violation fails the gate.
6. Require zero skips and zero flakes for safety-required cases.
7. Return `gate=insufficient-sample` when fewer than the pre-registered minimum number of cases are complete. Never convert a small sample to `pass`.
8. Include registered, complete, incomplete, and metric denominators plus explicit gate reasons in JSON and Markdown output.

## Acceptance

- `pass^k` and `pass@k` are visibly distinct and use the correct mathematical definitions.
- Incomplete cases remain visible by ID and status.
- A retry success does not erase the original trial failure or make that case pass `pass^k`.
- Anchor violations, safety skips, safety flakes, excess flake rate, and incomplete evidence are visible in gate reasons.
- Product defaults, product locks, approval semantics, and automation schedules are unchanged.
- README files remain unchanged because this package changes only the internal evaluation report.
"},{"path":"harness/specs/rules/reliability-aggregation-boundary.md","content":"# Reliability aggregation boundary

## Scope

This rule applies to `scripts/agent-dev-benefit-eval.mjs`, `scripts/lib/reliability-aggregation.mjs`, and `shared/agent-dev/reliability-fixture.json`.

## Required semantics

- The source of truth is the deterministic fixture. `k`, `minCases`, and the flake threshold are pre-registered in that fixture.
- `pass^k` is the fraction of complete eligible cases whose first attempt passed in every one of the first `k` trials.
- `pass@k` is the fraction of complete eligible cases whose first attempt passed in at least one of the first `k` trials.
- `pass^k` and `pass@k` must not be renamed, conflated, or substituted for one another.
- A trial is successful only according to its anchor expectation: positive/neutral trials require `pass`; negative trials require `reject`.
- A flake requires a failed first attempt followed by a successful fixed rerun. The successful rerun does not replace the failed first attempt and does not wash out the original gate failure.
- `missing`, `timeout`, `crash`, and `skip` are incomplete. Their cases remain in the report with IDs and statuses but are excluded from complete-case denominators.
- Safety-required cases must have zero skips and zero flakes.
- Positive anchors must pass all trials. Negative anchors must reject all trials. Any anchor violation sets the gate to `fail` when the sample is sufficient.
- Fewer than the pre-registered complete-case minimum must set `gate=insufficient-sample`; a small sample is never reported as `pass`.
- The report must include raw denominators, `pass^k`, `pass@k`, per-trial success, flake, incomplete cases, anchors, gate, and reasons.

## Prohibited claims and changes

- Do not describe the deterministic oracle as evidence from a real provider, real model, human participants, or generalization.
- Do not modify product defaults, product locks, approval semantics, dependency configuration, or automation schedules.
- Do not add a new metric service or platform; extend the existing Agent Dev benefit report.
"},{"path":"docs/dev/harness-gap-closure/e01-reliability-aggregation.md","content":"# E01 reliability aggregation closure

## Outcome

The existing Agent Dev benefit evaluation now includes a deterministic reliability section backed by `shared/agent-dev/reliability-fixture.json` and aggregated by `scripts/lib/reliability-aggregation.mjs`.

The report contains:

- the registered and complete-case denominators;
- `pass^k` and `pass@k` as separate metrics;
- per-trial success and retained per-trial outcomes;
- first-failure-preserving flake aggregation;
- explicit `missing`, `timeout`, `crash`, and `skip` cases;
- positive and negative anchor aggregation;
- the safety zero-skip/zero-flake rule;
- the pre-registered sample gate and explicit reasons.

The fixture uses `k=3`, a minimum of `20` complete cases, and a flake threshold of `0.1`. It is explicitly marked as a deterministic in-repo oracle. No conclusion is made about real providers, real models, people, or generalization.

## Boundary review

This package changes only internal evaluation and acceptance artifacts. It does not expose a new user-facing interface, change a product default, alter a product lock, change approval semantics, add a dependency, or schedule automation.

The four-language README review therefore requires no README edit. The no-user-visible-change conclusion is recorded here instead.

## Gate semantics

`insufficient-sample` takes precedence when the complete-case count is below the fixture minimum. Otherwise, incomplete evidence, an excessive flake rate, a safety skip or flake, or an anchor violation produces `fail`. The deterministic fixture intentionally retains incomplete states and two non-safety flakes so that the report demonstrates all aggregation paths.

## Verification record

The required verification scope is the targeted unit tests, runtime/core type checks, scoped lint, harness validation and dry-run, a zero-hit credential scan, and readable `SHA256SUMS`. These checks must be recorded by the release or acceptance harness; this document does not fabricate their results.
