{"edits":[{"path":"scripts/lib/reliability-aggregation.mjs","content":"const INCOMPLETE_STATUSES = new Set(['missing', 'timeout', 'crash', 'skip']);
const VALID_OUTCOMES = new Set(['pass', 'fail', 'reject', ...INCOMPLETE_STATUSES]);

function isObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function outcomeOf(trial) {
  if (!isObject(trial)) return 'missing';
  if (Array.isArray(trial.attempts) && trial.attempts.length > 0) return trial.attempts[0];
  return trial.outcome ?? 'missing';
}

function attemptsOf(trial) {
  if (!isObject(trial)) return ['missing'];
  if (Array.isArray(trial.attempts) && trial.attempts.length > 0) return trial.attempts;
  return [trial.outcome ?? 'missing'];
}

function expectedOutcome(anchor) {
  if (anchor === 'positive') return 'pass';
  if (anchor === 'negative') return 'reject';
  return 'pass';
}

function trialSucceeded(trial, anchor) {
  return outcomeOf(trial) === expectedOutcome(anchor);
}

function assertConfig(config) {
  if (!isObject(config)) throw new TypeError('Reliability config must be an object.');
  if (!Number.isInteger(config.k) || config.k < 1) throw new TypeError('Reliability k must be a positive integer.');
  if (!Number.isInteger(config.minCases) || config.minCases < 1) throw new TypeError('Reliability minCases must be a positive integer.');
  if (typeof config.flakeThreshold !== 'number' || config.flakeThreshold < 0 || config.flakeThreshold > 1) {
    throw new TypeError('Reliability flakeThreshold must be between 0 and 1.');
  }
}

/**
 * Aggregate a deterministic reliability fixture.
 *
 * A trial's first attempt is its outcome. Later attempts are fixed reruns used
 * to identify flakes; a rerun never replaces the first failure. A case with any
 * incomplete status is retained but excluded from all complete-case
 * denominators. Negative anchors count `reject` as the expected outcome and
 * are reported separately from pass^k and pass@k.
 */
export function aggregateReliability(config, fixture) {
  assertConfig(config);
  if (!isObject(fixture) || !Array.isArray(fixture.cases)) {
    throw new TypeError('Reliability fixture must contain a cases array.');
  }

  const cases = fixture.cases;
  const completeCases = [];
  const incompleteCases = [];
  const byStatus = Object.fromEntries([...INCOMPLETE_STATUSES].map((status) => [status, 0]));

  for (const testCase of cases) {
    if (!isObject(testCase) || !Array.isArray(testCase.trials)) {
      throw new TypeError('Every reliability case must have a trials array.');
    }
    const statuses = new Set();
    for (const trial of testCase.trials) {
      for (const attempt of attemptsOf(trial)) {
        if (INCOMPLETE_STATUSES.has(attempt)) statuses.add(attempt);
        if (!VALID_OUTCOMES.has(attempt)) {
          throw new TypeError(`Unknown reliability outcome: ${String(attempt)}`);
        }
      }
    }
    const record = {
      id: String(testCase.id ?? 'unknown'),
      anchor: testCase.anchor ?? null,
      safety: testCase.safety === true,
      required: testCase.required !== false,
      statuses: [...statuses],
      trials: testCase.trials,
    };
    if (statuses.size > 0) {
      incompleteCases.push(record);
      for (const status of statuses) byStatus[status] += 1;
    } else {
      completeCases.push(record);
    }
  }

  const metricCases = completeCases.filter((testCase) => testCase.anchor !== 'negative');
  const passPowKNumerator = metricCases.filter((testCase) =>
    testCase.trials.slice(0, config.k).every((trial) => outcomeOf(trial) === 'pass')).length;
  const passAtKNumerator = metricCases.filter((testCase) =>
    testCase.trials.slice(0, config.k).some((trial) => outcomeOf(trial) === 'pass')).length;

  const trialRows = [];
  const outcomeCounts = { pass: 0, fail: 0, reject: 0 };
  let successfulTrials = 0;
  for (const testCase of completeCases) {
    testCase.trials.forEach((trial, index) => {
      const initial = outcomeOf(trial);
      const attempts = attemptsOf(trial);
      const success = trialSucceeded(trial, testCase.anchor);
      if (success) successfulTrials += 1;
      if (Object.hasOwn(outcomeCounts, initial)) outcomeCounts[initial] += 1;
      trialRows.push({
        caseId: testCase.id,
        trial: index + 1,
        initialOutcome: initial,
        attempts,
        expectedOutcome: expectedOutcome(testCase.anchor),
        success,
      });
    });
  }

  const flakeCases = completeCases.filter((testCase) => testCase.trials.some((trial) => {
    const attempts = attemptsOf(trial);
    return attempts[0] === 'fail' && attempts.slice(1).some((attempt) => attempt === 'pass');
  }));
  const flakeCaseIds = flakeCases.map((testCase) => testCase.id);
  const flakeRate = completeCases.length === 0 ? 0 : flakeCases.length / completeCases.length;

  const anchorResults = {
    positive: { total: 0, passed: 0, failed: 0, failedCaseIds: [] },
    negative: { total: 0, passed: 0, failed: 0, failedCaseIds: [] },
  };
  for (const anchor of ['positive', 'negative']) {
    const anchored = completeCases.filter((testCase) => testCase.anchor === anchor);
    anchorResults[anchor].total = anchored.length;
    for (const testCase of anchored) {
      const passed = testCase.trials.every((trial) => trialSucceeded(trial, anchor));
      if (passed) anchorResults[anchor].passed += 1;
      else {
        anchorResults[anchor].failed += 1;
        anchorResults[anchor].failedCaseIds.push(testCase.id);
      }
    }
  }

  const reasons = [];
  if (completeCases.length < config.minCases) {
    reasons.push(`complete cases ${completeCases.length} are below the pre-registered minimum ${config.minCases}`);
  }
  if (incompleteCases.length > 0) {
    reasons.push(`${incompleteCases.length} incomplete case(s) were retained and excluded from denominators`);
  }
  if (flakeRate > config.flakeThreshold) {
    reasons.push(`flake rate ${flakeRate.toFixed(4)} exceeds the pre-registered threshold ${config.flakeThreshold}`);
  }
  const unsafeSkipCases = incompleteCases.filter((testCase) => testCase.safety && testCase.statuses.includes('skip')).map((testCase) => testCase.id);
  const unsafeFlakeCases = flakeCases.filter((testCase) => testCase.safety).map((testCase) => testCase.id);
  if (unsafeSkipCases.length > 0) reasons.push(`safety cases skipped: ${unsafeSkipCases.join(', ')}`);
  if (unsafeFlakeCases.length > 0) reasons.push(`safety cases flaked: ${unsafeFlakeCases.join(', ')}`);
  if (anchorResults.positive.failed > 0) {
    reasons.push(`positive anchor violation: ${anchorResults.positive.failedCaseIds.join(', ')}`);
  }
  if (anchorResults.negative.failed > 0) {
    reasons.push(`negative anchor violation: ${anchorResults.negative.failedCaseIds.join(', ')}`);
  }

  let gate = 'pass';
  if (completeCases.length < config.minCases) gate = 'insufficient-sample';
  else if (reasons.length > 0) gate = 'fail';

  return {
    oracle: fixture.oracle ?? 'deterministic-fixture',
    deterministic: fixture.deterministic === true,
    k: config.k,
    minCases: config.minCases,
    flakeThreshold: config.flakeThreshold,
    rawDenominator: {
      registeredCases: cases.length,
      completeCases: completeCases.length,
      incompleteCases: incompleteCases.length,
      metricCases: metricCases.length,
    },
    passPowK: {
      numerator: passPowKNumerator,
      denominator: metricCases.length,
      rate: metricCases.length === 0 ? 0 : passPowKNumerator / metricCases.length,
      definition: 'complete eligible cases whose first attempt passed in all k trials',
    },
    passAtK: {
      numerator: passAtKNumerator,
      denominator: metricCases.length,
      rate: metricCases.length === 0 ? 0 : passAtKNumerator / metricCases.length,
      definition: 'complete eligible cases whose first attempt passed in at least one of k trials',
    },
    trialSuccess: {
      successful: successfulTrials,
      total: trialRows.length,
      rate: trialRows.length === 0 ? 0 : successfulTrials / trialRows.length,
      outcomeCounts,
      trials: trialRows,
    },
    flake: {
      cases: flakeCases.length,
      denominator: completeCases.length,
      rate: flakeRate,
      threshold: config.flakeThreshold,
      caseIds: flakeCaseIds,
      definition: 'first attempt failed and a fixed rerun later passed',
    },
    incomplete: {
      count: incompleteCases.length,
      byStatus,
      cases: incompleteCases.map((testCase) => ({
        id: testCase.id,
        statuses: testCase.statuses,
        safety: testCase.safety,
        anchor: testCase.anchor,
      })),
    },
    anchors: anchorResults,
    gate,
    reasons,
  };
}

export { INCOMPLETE_STATUSES };
"},{"path":"scripts/lib/reliability-aggregation.d.mts","content":"export type ReliabilityOutcome = 'pass' | 'fail' | 'reject' | 'missing' | 'timeout' | 'crash' | 'skip';

export interface ReliabilityTrial {
  outcome?: ReliabilityOutcome;
  attempts?: ReliabilityOutcome[];
}

export interface ReliabilityCase {
  id: string;
  anchor?: 'positive' | 'negative' | null;
  safety?: boolean;
  required?: boolean;
  trials: ReliabilityTrial[];
}

export interface ReliabilityConfig {
  k: number;
  minCases: number;
  flakeThreshold: number;
}

export interface ReliabilityFixture {
  oracle?: string;
  deterministic?: boolean;
  cases: ReliabilityCase[];
}

export interface ReliabilityRate {
  numerator: number;
  denominator: number;
  rate: number;
  definition: string;
}

export interface ReliabilityResult {
  oracle: string;
  deterministic: boolean;
  k: number;
  minCases: number;
  flakeThreshold: number;
  rawDenominator: {
    registeredCases: number;
    completeCases: number;
    incompleteCases: number;
    metricCases: number;
  };
  passPowK: ReliabilityRate;
  passAtK: ReliabilityRate;
  trialSuccess: {
    successful: number;
    total: number;
    rate: number;
    outcomeCounts: Record<'pass' | 'fail' | 'reject', number>;
    trials: Array<{
      caseId: string;
      trial: number;
      initialOutcome: ReliabilityOutcome;
      attempts: ReliabilityOutcome[];
      expectedOutcome: 'pass' | 'reject';
      success: boolean;
    }>;
  };
  flake: {
    cases: number;
    denominator: number;
    rate: number;
    threshold: number;
    caseIds: string[];
    definition: string;
  };
  incomplete: {
    count: number;
    byStatus: Record<'missing' | 'timeout' | 'crash' | 'skip', number>;
    cases: Array<{
      id: string;
      statuses: Array<'missing' | 'timeout' | 'crash' | 'skip'>;
      safety: boolean;
      anchor: 'positive' | 'negative' | null;
    }>;
  };
  anchors: {
    positive: { total: number; passed: number; failed: number; failedCaseIds: string[] };
    negative: { total: number; passed: number; failed: number; failedCaseIds: string[] };
  };
  gate: 'pass' | 'fail' | 'insufficient-sample';
  reasons: string[];
}

export declare function aggregateReliability(config: ReliabilityConfig, fixture: ReliabilityFixture): ReliabilityResult;

export declare const INCOMPLETE_STATUSES: ReadonlySet<ReliabilityOutcome>;
